CREATE TABLE owner (id INTEGER PRIMARY KEY CHECK(id=1), password_hash TEXT NOT NULL);
CREATE TABLE credentials (hash TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('session','upload','read','admin')), created_at TEXT NOT NULL, expires_at TEXT);
CREATE TABLE imports (id TEXT PRIMARY KEY, state TEXT NOT NULL DEFAULT 'uploading', recorder_timezone TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE uploads (id TEXT PRIMARY KEY, import_id TEXT NOT NULL REFERENCES imports(id), filename TEXT NOT NULL, relative_path TEXT NOT NULL, length INTEGER NOT NULL CHECK(length>0), offset INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'uploading', pcm_hash TEXT, format_json TEXT, original_name TEXT NOT NULL, claimed_pcm_hash TEXT, failure TEXT);
CREATE TABLE entries (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, title TEXT NOT NULL, title_manual INTEGER NOT NULL DEFAULT 0, recorded_at TEXT, duration_ms INTEGER NOT NULL, timezone TEXT NOT NULL, stage TEXT NOT NULL, active_stage TEXT, failure TEXT, warnings TEXT NOT NULL DEFAULT '[]', summary TEXT, audio_path TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE entry_sources (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, upload_id TEXT NOT NULL REFERENCES uploads(id), position INTEGER NOT NULL, offset_ms INTEGER NOT NULL, recorded_at TEXT, PRIMARY KEY(entry_id,upload_id));
CREATE TABLE people (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE speakers (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, label TEXT NOT NULL, person_id TEXT REFERENCES people(id) ON DELETE SET NULL, state TEXT NOT NULL DEFAULT 'unknown', evidence TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(entry_id,label));
CREATE TABLE segments (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, position INTEGER NOT NULL, speaker TEXT NOT NULL, start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL, text TEXT NOT NULL, UNIQUE(entry_id,position));
CREATE INDEX segments_entry ON segments(entry_id,position);
CREATE TABLE labels (name TEXT PRIMARY KEY);
CREATE TABLE entry_labels (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, label TEXT NOT NULL REFERENCES labels(name), PRIMARY KEY(entry_id,label));
CREATE TABLE voice_samples (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, speaker TEXT NOT NULL, model TEXT NOT NULL, vector_json TEXT NOT NULL, provenance TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(entry_id,speaker,model));
CREATE TABLE voice_probes (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, speaker TEXT NOT NULL, model TEXT NOT NULL, vector_json TEXT NOT NULL, PRIMARY KEY(entry_id,speaker,model));
CREATE TABLE parts (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, part INTEGER NOT NULL, state TEXT NOT NULL, raw_json TEXT, PRIMARY KEY(entry_id,part));
CREATE TABLE passages (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, position INTEGER NOT NULL, start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL, text TEXT NOT NULL, embedding TEXT);
CREATE INDEX passages_entry ON passages(entry_id);
CREATE VIRTUAL TABLE passage_fts USING fts5(id UNINDEXED, entry_id UNINDEXED, title, text, tokenize='unicode61');
CREATE TRIGGER delete_entry_fts AFTER DELETE ON entries BEGIN DELETE FROM passage_fts WHERE entry_id=old.id; END;
CREATE INDEX uploads_import ON uploads(import_id);
